unsigned CtrNightWild_Species(unsigned map, unsigned area, unsigned slot, unsigned species, bool night, bool national)
{
    for (unsigned i = 0; i < sizeof(sNightRules) / sizeof(sNightRules[0]); ++i)
    {
        unsigned to = national ? sNightRules[i].johto : sNightRules[i].kanto;

        if (sNightRules[i].map != map || sNightRules[i].area != area || sNightRules[i].from != species
         || (sNightRules[i].slot >= 0 && (unsigned)sNightRules[i].slot != slot)
         || (sNightRules[i].when == CTR_WILD_NIGHT) != night)
            continue;
        return to != SPECIES_NONE ? to : species;
    }
    return species;
}

#ifndef CTR_HOST_TEST
unsigned CtrNightWild_Second(void)
{
    return (unsigned)((osGetTime() / 1000u) % 86400u);
}
#endif
